@Composable private fun ProjectDetail(db:MindRelayDb,id:Long,rev:Int,back:()->Unit,go:(S,T)->Unit,refresh:()->Unit){val p=db.project(id)?:return;val sessions=remember(rev,id){db.sessions(id)};Scaffold(topBar={Header(p.name,back)},containerColor=MaterialTheme.colorScheme.surface){pad->Column(Modifier.verticalScroll(rememberScrollState()).padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){AssistChip({},label={Text(p.status)});CardX("Current state",p.currentState.ifBlank{"Add what is true right now."});CardX("Next action",p.nextAction.ifBlank{"Add one concrete next step."},MaterialTheme.colorScheme.tertiaryContainer);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(3.dp)){Button({val a=sessions.firstOrNull{it.status=="Active"}?.id?:db.startSession(id,"Session ${sessions.size+1}");refresh();go(S.Session(a))},Modifier.weight(1f),shape=RoundedCornerShape(28.dp,8.dp,8.dp,28.dp)){Text("Resume session")};Button({db.updateProject(p.copy(goalNotes=(p.goalNotes+"\nProject note").trim()));refresh()},Modifier.weight(1f),colors=ButtonDefaults.buttonColors(containerColor=MaterialTheme.colorScheme.secondaryContainer,contentColor=MaterialTheme.colorScheme.onSecondaryContainer),shape=RoundedCornerShape(8.dp,28.dp,28.dp,8.dp)){Text("Add note")}};Section("Recent sessions");sessions.take(10).forEachIndexed{i,s->Item(i,sessions.size.coerceAtMost(10),Icons.Rounded.Schedule,s.title,"${s.status} · ${duration(s.startedAt,s.endedAt)}"){go(S.Session(s.id))}};Section("Linked memories");db.memories().filter{it.projectId==id}.forEach{m->Item(0,1,Icons.Rounded.Bookmark,m.title,m.type){go(S.Memory(m.id))}}}}}

@Composable private fun SessionScreen(db:MindRelayDb,id:Long,rev:Int,back:()->Unit,go:(S,T)->Unit,refresh:()->Unit){val s=db.session(id)?:return;val p=db.project(s.projectId);val e=remember(rev,id){db.sessionEntries(id)};var tab by rememberSaveable{mutableStateOf("Log")};var add by remember{mutableStateOf(false)};val filtered=e.filter{tab=="Log"||it.kind==when(tab){"Discoveries"->"Discovery";"Questions"->"Question";else->tab}};Scaffold(topBar={Header("Session ${s.id}",back)},floatingActionButton={AddFab({add=true},tonal=true)}){pad->LazyColumn(Modifier.padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp),contentPadding=PaddingValues(bottom=96.dp)){item{Text(p?.name?:"Project")};item{AssistChip({},label={Text("${s.status} · ${duration(s.startedAt,s.endedAt)}")})};item{Chips(listOf("Log","Discoveries","Questions"),tab){tab=it}};if(filtered.isEmpty())item{Empty("Nothing logged yet","Use + to record the work as it happens.",Icons.Rounded.Notes)}else items(filtered){x->Item(0,1,entryIcon(x.kind),x.body,"${SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(x.createdAt))} · ${x.kind}")};item{CardX("Current next action",p?.nextAction?.ifBlank{"Add a next action"}?:"Add a next action")};item{Button({go(S.End(id),T.Up)},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(28.dp)){Icon(Icons.Rounded.Flag,null);Spacer(Modifier.width(8.dp));Text("End session & write handoff")}}}};if(add)AddEntrySheet(db,id,{add=false;refresh()})}
private fun entryIcon(k:String)=when(k){"Problem"->Icons.Rounded.Warning;"Discovery"->Icons.Rounded.Lightbulb;"Question"->Icons.Rounded.Help;"Decision"->Icons.Rounded.Flag;"Task"->Icons.Rounded.ShoppingCart;else->Icons.Rounded.Notes}
@Composable private fun AddEntrySheet(db:MindRelayDb,id:Long,close:()->Unit){var k by rememberSaveable{mutableStateOf("Note")};var body by rememberSaveable{mutableStateOf("")};ModalBottomSheet(close){Column(Modifier.fillMaxWidth().padding(20.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Add to session",style=MaterialTheme.typography.titleLargeEmphasized);Chips(listOf("Note","Discovery","Question","Decision","Task"),k){k=it};OutlinedTextField(body,{body=it},Modifier.fillMaxWidth(),label={Text("What happened?")},minLines=3);Button(body.isNotBlank(),{db.addSessionEntry(id,k,body);close()},Modifier.fillMaxWidth()){Text("Add entry")};Spacer(Modifier.height(12.dp))}}}

@Composable private fun EndSession(db:MindRelayDb,id:Long,back:()->Unit,go:(S,T)->Unit,refresh:()->Unit){val s=db.session(id)?:return;var c by rememberSaveable{mutableStateOf("")};var d by rememberSaveable{mutableStateOf("")};var u by rememberSaveable{mutableStateOf("")};var n by rememberSaveable{mutableStateOf(db.project(s.projectId)?.nextAction?:"")};var promote by rememberSaveable{mutableStateOf(true)};Scaffold(topBar={Header("End session",back)}){pad->Column(Modifier.verticalScroll(rememberScrollState()).padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Write a handoff for Future You.",style=MaterialTheme.typography.titleMediumEmphasized);OutlinedTextField(c,{c=it},Modifier.fillMaxWidth(),label={Text("What did I complete?")},minLines=2);OutlinedTextField(d,{d=it},Modifier.fillMaxWidth(),label={Text("What did I discover?")},minLines=2);OutlinedTextField(u,{u=it},Modifier.fillMaxWidth(),label={Text("What is unresolved?")},minLines=2);OutlinedTextField(n,{n=it},Modifier.fillMaxWidth(),label={Text("Single next action")},minLines=2);Row(verticalAlignment=Alignment.CenterVertically){Checkbox(promote,{promote=it});Text("Promote the discovery above to Memory")};Button(n.isNotBlank()||c.isNotBlank()||d.isNotBlank()||u.isNotBlank(),{db.finishSessionWithHandoff(id,s.projectId,c,d,u,n,promote);refresh();go(S.Project(s.projectId),T.Down)},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(28.dp)){Text("Save handoff & end session")}}}}

@Composable private fun Memories(db:MindRelayDb,rev:Int,root:(S)->Unit,go:(S,T)->Unit,refresh:()->Unit){var f by rememberSaveable{mutableStateOf("All")};var q by rememberSaveable{mutableStateOf("")};val ms=remember(rev,f,q){db.memories(f).filter{q.isBlank()||it.title.contains(q,true)||it.body.contains(q,true)||it.tags.contains(q,true)}};Scaffold(topBar={Header("Memories")},floatingActionButton={AddFab{go(S.NewMemory(),T.Up)}},bottomBar={Nav(S.Memories,root)}){p->LazyColumn(Modifier.padding(p).padding(16.dp),verticalArrangement=Arrangement.spacedBy(3.dp),contentPadding=PaddingValues(bottom=96.dp)){item{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth().height(56.dp),singleLine=true,shape=CircleShape,placeholder={Text("Search memories...")},leadingIcon={Icon(Icons.Rounded.Search,null)},trailingIcon={Icon(Icons.Rounded.Tune,null)})};item{Chips(listOf("All","Fixes","People","Ideas","Places"),f){f=it}};if(ms.isEmpty())item{Empty("No memories yet","Convert your best knowledge into something Future You can find.",Icons.Rounded.Bookmark)}else items(ms){m->Item(0,1,memoryIcon(m.type),m.title,"${m.type}${if(m.tags.isBlank())"" else " · ${m.tags}"}${m.revisitAt?.let{" · Revisit ${SimpleDateFormat("MMM d",Locale.getDefault()).format(Date(it))}"}?:""}"){go(S.Memory(m.id))}}}}}
private fun memoryIcon(t:String)=when(t){"Fix"->Icons.Rounded.Build;"Person"->Icons.Rounded.Person;"Place"->Icons.Rounded.Place;"Recipe"->Icons.Rounded.Restaurant;else->Icons.Rounded.Bookmark}

@Composable private fun MemoryDetail(db:MindRelayDb,id:Long,rev:Int,back:()->Unit,go:(S,T)->Unit,refresh:()->Unit){val m=db.memory(id)?:return;Scaffold(topBar={Header("Memory",back)}){p->Column(Modifier.verticalScroll(rememberScrollState()).padding(p).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Chips(listOf(m.type)+m.tags.split(" ").filter{it.isNotBlank()},m.type){};Text(m.title,style=MaterialTheme.typography.headlineSmallEmphasized,Modifier.fillMaxWidth(),textAlign=TextAlign.Center);CardX(body=m.body);Item(0,1,Icons.Rounded.FolderOpen,"Related project",m.projectId?.let{db.project(it)?.name}?:"None"){m.projectId?.let{go(S.Project(it))}};Item(0,1,Icons.Rounded.Schedule,"Source session",m.sourceSessionId?.let{db.session(it)?.title}?:"None"){m.sourceSessionId?.let{go(S.Session(it))}};Item(0,1,Icons.Rounded.EventRepeat,"Revisit",m.revisitAt?.let{SimpleDateFormat("MMM d, yyyy",Locale.getDefault()).format(Date(it))}?:"Not scheduled");OutlinedButton({db.archiveMemory(id);refresh();back()},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(28.dp)){Icon(Icons.Rounded.Archive,null);Spacer(Modifier.width(8.dp));Text("Archive")}}}}

@Composable private fun NewMemoryScreen(db:MindRelayDb,src:Long?,sess:Long?,back:()->Unit,go:(S,T)->Unit,refresh:()->Unit){var title by rememberSaveable{mutableStateOf("")};var type by rememberSaveable{mutableStateOf("Fix")};var body by rememberSaveable{mutableStateOf("")};var tags by rememberSaveable{mutableStateOf("")};var project by rememberSaveable{mutableLongStateOf(0)};var revisit by rememberSaveable{mutableStateOf("")};var menu by remember{mutableStateOf(false)};val projects=remember{db.projects()};val types=listOf("Fix","Person","Idea","Place","Recipe","Note","Other");Scaffold(topBar={Header("New Memory",back)}){p->Column(Modifier.verticalScroll(rememberScrollState()).padding(p).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(title,{title=it},Modifier.fillMaxWidth(),label={Text("Title")},supportingText={Text("What will Future You search for?")});Box(Modifier.fillMaxWidth()){OutlinedTextField(type,{},Modifier.fillMaxWidth().clickable{menu=true},readOnly=true,label={Text("Type")},trailingIcon={Icon(Icons.Rounded.ExpandMore,null)});DropdownMenu(menu,{menu=false}){types.forEach{x->DropdownMenuItem({Text(x)},{type=x;menu=false})}}};OutlinedTextField(body,{body=it},Modifier.fillMaxWidth(),label={Text("Durable note")},minLines=5,supportingText={Text("Write it for Future You, not just Present You.")});OutlinedTextField(tags,{tags=it},Modifier.fillMaxWidth(),label={Text("Tags")});Item(0,1,Icons.Rounded.FolderOpen,"Linked project (optional)",projects.firstOrNull{it.id==project}?.name?:"None"){project=projects.firstOrNull()?.id?:0};Item(0,1,Icons.Rounded.EventRepeat,"Revisit date (optional)",revisit.ifBlank{"Not set"});Button(title.isNotBlank()&&body.isNotBlank(),{val n=db.insertMemory(title,type,body,tags,project.takeIf{it!=0L},src,sess,parseDate(revisit));src?.let{db.archiveCapture(it)};refresh();go(S.Memory(n),T.Right)},Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(28.dp)){Text("Save Memory")}}}}

