@Composable private fun Backup(db:MindRelayDb,back:()->Unit,refresh:()->Unit){val c=LocalContext.current;var preview by remember{mutableStateOf<String?>(null)};var msg by remember{mutableStateOf<String?>(null)};val save=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){u->if(u!=null)runCatching{c.contentResolver.openOutputStream(u)?.use{it.write(db.exportJson().toByteArray())}?:error("Unable to open destination")}.onSuccess{msg="Backup exported"}.onFailure{msg=it.message?:"Export failed"}};val open=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u->if(u!=null)runCatching{c.contentResolver.openInputStream(u)?.bufferedReader()?.use{it.readText()}?:error("Unable to read backup")}.onSuccess{json->runCatching{JSONObject(json);preview=json}.onFailure{msg=it.message?:"Invalid backup"}}.onFailure{msg=it.message?:"Import failed"}};Scaffold(topBar={Header("Data & Backup",back)}){p->Column(Modifier.verticalScroll(rememberScrollState()).padding(p).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){CardX("Your data stays on your device","MindRelay stores everything locally in SQLite. There is no account, no cloud sync, and no silent upload. You own your data.",MaterialTheme.colorScheme.tertiaryContainer);Item(0,3,Icons.Rounded.FileDownload,"Export backup","Save projects, sessions, memories, captures, tasks to a file"){save.launch("mindrelay-backup.json")};Item(1,3,Icons.Rounded.FileUpload,"Import backup","Validate schema before merging"){open.launch(arrayOf("application/json","text/plain"))};Item(2,3,Icons.Rounded.Restore,"Restore from backup","Preview before replacing data"){open.launch(arrayOf("application/json","text/plain"))};Section("Backup includes");Text("""• Projects & current state
• Sessions & chronological entries
• Memories with tags and revisit dates
• Captures with provenance
• Tasks
• All relationships and metadata""");Text("Keystore-backed encrypted exports, app lock, biometric unlock.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};if(preview!=null)AlertDialog(onDismissRequest={preview=null},title={Text("Backup preview")},text={Text("Schema valid. Ready to import.")},confirmButton={Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){TextButton({val result=db.importJson(preview!!,false);msg=result.second;refresh();preview=null}){Text("Merge")};Button({val result=db.importJson(preview!!,true);msg=result.second;refresh();preview=null}){Text("Replace")}}},dismissButton={TextButton({preview=null}){Text("Cancel")}});if(msg!=null)AlertDialog(onDismissRequest={msg=null},text={Text(msg!!)},confirmButton={TextButton({msg=null}){Text("OK")}})}

private fun ago(x:Long)=when(val m=(System.currentTimeMillis()-x).coerceAtLeast(0)/60000){in 0..0->"just now";in 1..59->"$m min ago";in 60..1439->"${m/60} hour${if(m/60==1L)""else"s"} ago";in 1440..2879->"yesterday";else->"${m/1440} days ago"}
private fun duration(s:Long,e:Long?):String{val m=((e?:System.currentTimeMillis())-s).coerceAtLeast(0)/60000;return "${m/60}h ${m%60}m"}
private fun parseDate(x:String)=runCatching{SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).parse(x.trim())?.time}.getOrNull()
